package com.spinplayer.app;
import java.io.*;import java.net.*;import java.util.*;import java.text.Normalizer;import com.grack.nanojson.*;
/** Search and rank providers independently of Android; never invents timestamps. */
public final class LyricsProvider {
 public interface Fetcher {String get(String url)throws Exception;}
 public static final class Candidate {public String key,title,artist,album,source,text;public long providerId;public double duration,score;public boolean synced,instrumental,confident;}
 public static final class Result {public final List<Candidate> items=new ArrayList<>();public final List<String> warnings=new ArrayList<>();public final Map<String,String> statuses=new LinkedHashMap<>();}
 public static String normalize(String s){return Normalizer.normalize(s==null?"":s,Normalizer.Form.NFKC).toLowerCase(Locale.ROOT).replace('ё','е').replaceAll("[^\\p{L}\\p{N}]+"," ").trim().replaceAll("\\s+"," ");}
 public static String cleanTitle(String s){return s.replaceAll("(?iu)[\\[(]\\s*(?:official\\s+(?:audio|video|music video|lyric video)|lyrics?|audio|video|hd|hq|4k|официальный\\s+(?:клип|аудио)|текст\\s+песни)\\s*[\\])]", " ").replaceAll("(?iu)\\s*[-–|]\\s*(?:official\\s+(?:audio|video|music video)|lyrics?|hd|4k)\\s*$", "").trim().replaceAll("\\s+"," ");}
 public static String cleanArtist(String s){return s.replaceFirst("(?iu)\\s*[-–]\\s*Topic\\s*$","").trim();}
 static Set<String> versions(String text){Set<String> out=new HashSet<>();String n=" "+normalize(text)+" ";String[][] groups={{"live","live","concert","концерт","концертная"},{"remix","remix","ремикс"},{"slowed","slowed","замедленная"},{"sped","sped","nightcore","ускоренная"},{"acoustic","acoustic","акустика","акустическая"},{"cover","cover","кавер"},{"instrumental","instrumental","инструментал"},{"demo","demo","демо"}};for(String[] g:groups)for(int i=1;i<g.length;i++)if(n.contains(" "+g[i]+" ")){out.add(g[0]);break;}return out;}
 static double similarity(String a,String b){a=normalize(a);b=normalize(b);if(a.isEmpty()||b.isEmpty())return 0;if(a.equals(b))return 1;Set<String> x=new HashSet<>(Arrays.asList(a.split(" "))),y=new HashSet<>(Arrays.asList(b.split(" ")));int same=0;for(String t:x)if(y.contains(t))same++;return 2.0*same/(x.size()+y.size());}
 static String text(JsonObject j,String field){String s=j.getString(field,"");return s==null?"":s.trim();}
 static void add(Result r,JsonObject j,String title,String artist,double duration,String album){if(j==null)return;String synced=text(j,"syncedLyrics"),plain=text(j,"plainLyrics");boolean instrumental=j.getBoolean("instrumental",false);if(synced.isEmpty()&&plain.isEmpty()&&!instrumental)return;Candidate c=new Candidate();c.providerId=j.getLong("id",0);c.key="lrclib:"+c.providerId;c.title=text(j,"trackName");c.artist=text(j,"artistName");c.album=text(j,"albumName");c.duration=j.getDouble("duration",0);c.source="LRCLIB";c.synced=synced.matches("(?s).*\\[\\d+:\\d{2}(?:[.:]\\d{1,3})?\\].*");c.text=c.synced?synced:plain;c.instrumental=instrumental;c.score=.45*similarity(cleanTitle(title),cleanTitle(c.title))+.35*similarity(cleanArtist(artist),cleanArtist(c.artist));boolean edition=versions(title).equals(versions(c.title));double delta=duration>0&&c.duration>0?Math.abs(duration-c.duration):Double.MAX_VALUE;if(delta<=2)c.score+=.2;else if(delta<=5)c.score+=.1;if(!edition)c.score-=.5;if(!album.isEmpty()&&normalize(album).equals(normalize(c.album)))c.score+=.02;c.confident=edition&&similarity(cleanTitle(title),cleanTitle(c.title))>=.95&&similarity(cleanArtist(artist),cleanArtist(c.artist))>=.95&&(duration<=0||delta<=2);for(Candidate old:r.items)if(old.key.equals(c.key))return;r.items.add(c);}
 static String enc(String s)throws Exception{return URLEncoder.encode(s,"UTF-8");}
 static String failure(Exception e){if(e instanceof RateLimited)return "rate_limited";String m=e.getMessage();if(m!=null&&m.matches("LyricsHttp[0-9]{3}"))return m;if(e instanceof java.net.UnknownHostException)return "dns_unavailable";if(e instanceof java.net.SocketTimeoutException)return "network_timeout";return "source_unavailable";}
 static boolean unavailable(Result r){for(String s:r.warnings)if(s.startsWith("lrclib:")&&!s.endsWith("LyricsHttp404"))return true;return false;}
 static void search(Result r,Fetcher f,String url,String title,String artist,double duration,String album){try{JsonArray a=JsonParser.array().from(f.get(url));for(int i=0;i<a.size();i++)add(r,a.getObject(i),title,artist,duration,album);}catch(Exception e){r.warnings.add(e instanceof RateLimited?"rate_limited":"lrclib:"+failure(e));}}
 public static Result find(String title,String artist,String album,double duration,Fetcher f)throws Exception{return find(title,artist,album,duration,f,"all",true);}
 public static Result find(String title,String artist,String album,double duration,Fetcher f,String source,boolean automatic)throws Exception{Result r=new Result();title=cleanTitle(title);artist=cleanArtist(artist);String prefix=artist+" - ";if(title.toLowerCase(Locale.ROOT).startsWith(prefix.toLowerCase(Locale.ROOT)))title=title.substring(prefix.length()).trim();if(title.isEmpty()||normalize(artist).equals("неизвестный исполнитель")||artist.trim().isEmpty()){r.warnings.add("missing_metadata");return r;}
 if(!Arrays.asList("all","lrclib","ovh","kugou","qq").contains(source))source="all";
 if(source.equals("all")||source.equals("lrclib")){
 String signature="track_name="+enc(title)+"&artist_name="+enc(artist);String exact="https://lrclib.net/api/get?"+signature;if(!album.isEmpty()&&!album.equals("Скачанное")&&!album.equals("Без альбома"))exact+="&album_name="+enc(album);if(duration>=1&&duration<=3600)exact+="&duration="+Math.round(duration);
 try{add(r,JsonParser.object().from(f.get(exact)),title,artist,duration,album);}catch(Exception e){r.warnings.add(e instanceof RateLimited?"rate_limited":"lrclib:"+failure(e));}
 boolean good=false;for(Candidate c:r.items)if(c.confident&&(c.synced||c.instrumental))good=true;
 if(!good&&!unavailable(r)&&!r.warnings.contains("rate_limited")){search(r,f,"https://lrclib.net/api/search?"+signature,title,artist,duration,album);good=false;for(Candidate c:r.items)if(c.confident&&c.synced)good=true;if(!good&&!unavailable(r)&&!r.warnings.contains("rate_limited"))search(r,f,"https://lrclib.net/api/search?q="+enc(artist+" "+title),title,artist,duration,album);}
 if(!good&&!unavailable(r)&&!r.warnings.contains("rate_limited"))search(r,f,"https://lrclib.net/api/search?track_name="+enc(title),title,artist,duration,album);
 status(r,"LRCLIB","lrclib");}
 boolean readable=false;for(Candidate c:r.items)if(c.confident)readable=true;
 if((source.equals("all")||source.equals("ovh"))&&(!automatic||!readable)){try{JsonObject j=JsonParser.object().from(f.get("https://api.lyrics.ovh/v1/"+enc(artist).replace("+","%20")+"/"+enc(title).replace("+","%20")));String plain=text(j,"lyrics");if(!plain.isEmpty()){Candidate c=new Candidate();c.key="ovh:"+normalize(artist+" "+title);c.title=title;c.artist=artist;c.album="";c.source="lyrics.ovh";c.text=plain;c.score=.5;c.confident=false;r.items.add(c);}}catch(Exception e){r.warnings.add("lyrics.ovh:"+failure(e));}status(r,"lyrics.ovh","lyrics.ovh");}
 boolean timed=false;for(Candidate c:r.items)if(c.confident&&(c.synced||c.instrumental))timed=true;
 if(!automatic||!timed)for(String extra:new String[]{"kugou","qq"})if(source.equals("all")||source.equals(extra)){
  try{String url="https://api.betterlyrics.org/"+extra+"/getLyrics?s="+enc(title)+"&a="+enc(artist)+"&al="+enc(album)+"&d="+Math.max(0,Math.round(duration));
   JsonObject j=JsonParser.object().from(f.get(url));String raw=text(j,"lyrics");if(!raw.isEmpty()){String body=extra.equals("qq")?qrcToLrc(raw):raw;
    if(!body.matches("(?s).*\\[\\d+:\\d{2}(?:[.:]\\d{1,3})?\\].*"))throw new IOException("InvalidLyricsFormat");
    Candidate c=new Candidate();c.key=extra+":"+normalize(artist+" "+title);c.source=extra.equals("qq")?"QQ · Better Lyrics":"KuGou · Better Lyrics";c.title=lrcTag(body,"ti",title);c.artist=lrcTag(body,"ar",artist);c.album=lrcTag(body,"al",album);c.text=body;c.synced=true;c.score=.55;c.confident=false;r.items.add(c);
   }
  }catch(Exception e){r.warnings.add(extra+":"+failure(e));}status(r,extra.equals("qq")?"QQ · Better Lyrics":"KuGou · Better Lyrics",extra);
 }
 r.items.sort((a,b)->{int confidence=Boolean.compare(b.confident,a.confident);if(confidence!=0)return confidence;int sync=Boolean.compare(b.synced,a.synced);if(sync!=0)return sync;return Double.compare(b.score,a.score);});int lrcCount=0;for(Iterator<Candidate> it=r.items.iterator();it.hasNext();)if(it.next().source.equals("LRCLIB")&&++lrcCount>9)it.remove();return r;}

 static void status(Result r,String name,String prefix){for(Candidate c:r.items)if(c.source.equals(name)){r.statuses.put(prefix,"found");return;}for(String w:r.warnings)if(w.startsWith(prefix+":")&&!w.endsWith("LyricsHttp404")){r.statuses.put(prefix,w.substring(prefix.length()+1));return;}if(prefix.equals("lrclib")&&r.warnings.contains("rate_limited")){r.statuses.put(prefix,"rate_limited");return;}r.statuses.put(prefix,"not_found");}
 static String lrcTag(String body,String tag,String fallback){java.util.regex.Matcher m=java.util.regex.Pattern.compile("(?im)^\\["+tag+":([^\\]]*)\\]").matcher(body);return m.find()&&!m.group(1).trim().isEmpty()?m.group(1).trim():fallback;}
 static String stamp(long ms){return String.format(Locale.US,"%02d:%02d.%03d",ms/60000,(ms/1000)%60,ms%1000);}
 public static String qrcToLrc(String raw)throws IOException{
  String body=raw;if(raw.trim().startsWith("<")){org.jsoup.nodes.Element el=org.jsoup.Jsoup.parse(raw,"",org.jsoup.parser.Parser.xmlParser()).selectFirst("[LyricContent]");if(el==null)throw new IOException("InvalidQrc");body=el.attr("LyricContent");}
  StringBuilder out=new StringBuilder();java.util.regex.Pattern header=java.util.regex.Pattern.compile("^\\[(\\d{1,9}),(\\d{1,9})\\](.*)$"),word=java.util.regex.Pattern.compile("\\((\\d{1,9}),(\\d{1,9})\\)");
  for(String line:body.split("\\r?\\n")){line=line.trim();if(line.matches("\\[(?:ti|ar|al|offset):[^\\]]*\\]")){out.append(line).append('\n');continue;}java.util.regex.Matcher h=header.matcher(line);if(!h.matches())continue;out.append('[').append(stamp(Long.parseLong(h.group(1)))).append(']');String rest=h.group(3);java.util.regex.Matcher w=word.matcher(rest);int from=0;while(w.find()){out.append('<').append(stamp(Long.parseLong(w.group(1)))).append('>').append(rest.substring(from,w.start()));from=w.end();}out.append(rest.substring(from)).append('\n');}
  if(out.toString().trim().isEmpty())throw new IOException("InvalidQrc");return out.toString();
 }
 public static final class RateLimited extends IOException{public RateLimited(){super("LyricsRateLimited");}}
 public interface Events {void log(String message);}
 public static final class HttpFetcher implements Fetcher {
  final Events events;public HttpFetcher(){this(s->{});}public HttpFetcher(Events e){events=e;}
  static long lastRequest=0;static final Map<String,Long> retryTimes=new HashMap<>();
  public String get(String url)throws Exception{boolean lrc=url.startsWith("https://lrclib.net/");synchronized(HttpFetcher.class){long now=System.currentTimeMillis();Long until=retryTimes.get(new URL(url).getHost());if(until!=null&&now<until)throw new RateLimited();if(lrc){long wait=300-(now-lastRequest);if(wait>0)Thread.sleep(wait);lastRequest=System.currentTimeMillis();}}
   if(Thread.currentThread().isInterrupted())throw new InterruptedIOException();String host=new URL(url).getHost();String endpoint=new URL(url).getPath().contains("search")?"search":new URL(url).getPath().contains("/get")?"get":"lyrics";long begin=System.nanoTime();events.log("LYRICS_HTTP_BEGIN host="+host+" endpoint="+endpoint);HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();c.setConnectTimeout(5000);c.setReadTimeout(8000);c.setRequestProperty("User-Agent","SPINPlayer/0.3.5 (https://vinyl-fold-test.eravalk.chatgpt.site/)");c.setRequestProperty("Accept","application/json");c.setRequestProperty("Accept-Encoding","identity");try{int status=c.getResponseCode();events.log("LYRICS_HTTP host="+host+" endpoint="+endpoint+" status="+status+" elapsed_ms="+(System.nanoTime()-begin)/1000000);if(status==429||status==503){long delay=60;String header=c.getHeaderField("Retry-After");try{delay=Long.parseLong(header);}catch(Exception ignored){if(header!=null)try{java.text.SimpleDateFormat fmt=new java.text.SimpleDateFormat("EEE, dd MMM yyyy HH:mm:ss zzz",Locale.US);delay=Math.max(1,(fmt.parse(header).getTime()-System.currentTimeMillis())/1000);}catch(Exception ignored2){}}synchronized(HttpFetcher.class){retryTimes.put(host,System.currentTimeMillis()+Math.min(86400,Math.max(1,delay))*1000L);}throw new RateLimited();}if(status!=200)throw new IOException("LyricsHttp"+status);String type=c.getContentType();if(type==null||!type.toLowerCase(Locale.ROOT).contains("json"))throw new IOException("LyricsNotJson");try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(Thread.currentThread().isInterrupted())throw new InterruptedIOException();if(out.size()+n>2*1024*1024)throw new IOException("LyricsTooLarge");out.write(b,0,n);}return out.toString("UTF-8");}}catch(Exception e){events.log("LYRICS_HTTP_FAILED host="+host+" endpoint="+endpoint+" kind="+e.getClass().getSimpleName()+" reason="+failure(e));throw e;}finally{c.disconnect();}}
 }
}
